export default function HomeScreen() {
  const { user, loading, signOut, completeOnboarding } = useAuth(); const { lang, setLang, t } = useI18n()
  if (user?.onboarding_completed) return <DatabaseMainApp name={user.display_name ?? 'Hrac'} nickname={user.nickname} onSignOut={signOut} />
  if (loading) return <View style={styles.container}><ActivityIndicator /><Text>{t.loading}</Text></View>
  if (user && !user.onboarding_completed) return <OnboardingScreen defaultName={user.display_name ?? ''} completeOnboarding={completeOnboarding} />
  if (user) return <MainApp name={user.display_name ?? 'Hráč'} onSignOut={signOut} />
  return <LoginScreen lang={lang} setLang={setLang} t={t} />
}

