function LegacyMainApp({ name, onSignOut }: { name: string; onSignOut: () => Promise<void> }) {
  const [tab, setTab] = useState<MainTab>('home')
  const titles: Record<MainTab, string> = { home: 'Domov', events: 'Eventy', ranking: 'Ranking', profile: 'Profil' }
  return <View style={mainStyles.mainApp}><View style={mainStyles.mainHeader}><View><Text style={mainStyles.headerBrand}>3×3 <Text style={styles.accent}>SPORT</Text></Text><Text style={mainStyles.headerTitle}>{titles[tab]}</Text></View><Pressable style={mainStyles.headerAction}><Text style={mainStyles.headerActionText}>⌕</Text></Pressable></View><ScrollView contentContainerStyle={mainStyles.mainContent}>{tab === 'home' && <HomeTab name={name} />}{tab === 'events' && <PlaceholderTab icon="▣" title="Eventy" description="Tu nájdeš turnaje, ligy a komunitné udalosti." />}{tab === 'ranking' && <PlaceholderTab icon="♜" title="Ranking" description="Tu bude rebríček hráčov a tímov." />}{tab === 'profile' && <ProfileTab name={name} onSignOut={onSignOut} />}</ScrollView><BottomNavigation active={tab} onChange={setTab} /></View>
}

function HomeTab({ name }: { name: string }) { return <><View style={[mainStyles.mainCard, mainStyles.heroCard]}><Text style={mainStyles.cardKicker}>VITAJ SPÄŤ</Text><Text style={mainStyles.homeGreeting}>{name}</Text><Text style={mainStyles.mainMuted}>Pripravený vyraziť na ihrisko?</Text></View><Text style={mainStyles.sectionTitle}>NAJBLIŽŠIE PRE TEBA</Text><View style={mainStyles.mainCard}><Text style={mainStyles.cardTitle}>Žiadne udalosti zatiaľ nemáš</Text><Text style={mainStyles.mainMuted}>Keď pridáme eventy, uvidíš ich tu.</Text></View></> }
function PlaceholderTab({ icon, title, description }: { icon: string; title: string; description: string }) { return <View style={mainStyles.emptyState}><Text style={mainStyles.emptyIcon}>{icon}</Text><Text style={mainStyles.emptyTitle}>{title}</Text><Text style={mainStyles.mainMuted}>{description}</Text></View> }
function ProfileTab({ name, onSignOut }: { name: string; onSignOut: () => Promise<void> }) { return <><View style={mainStyles.profileCard}><View style={mainStyles.avatar}><Text style={mainStyles.avatarText}>{name.slice(0, 1).toUpperCase()}</Text></View><Text style={mainStyles.profileName}>{name}</Text><Text style={mainStyles.mainMuted}>Hráč 3×3 SPORT</Text></View><View style={mainStyles.mainCard}><Text style={mainStyles.cardTitle}>Môj profil</Text><Text style={mainStyles.mainMuted}>Nastavenia a štatistiky doplníme neskôr.</Text></View><Pressable style={mainStyles.signOutButton} onPress={() => void onSignOut()}><Text style={mainStyles.signOutText}>Odhlásiť sa</Text></Pressable><BackendStatus /></> }
function BottomNavigation({ active, onChange }: { active: MainTab; onChange: (tab: MainTab) => void }) { const items: { key: MainTab; icon: string; label: string }[] = [{ key: 'home', icon: '⌂', label: 'Domov' }, { key: 'events', icon: '▣', label: 'Eventy' }, { key: 'ranking', icon: '♜', label: 'Ranking' }, { key: 'profile', icon: '♙', label: 'Profil' }]; return <View style={mainStyles.tabBar}>{items.map(item => <Pressable key={item.key} style={mainStyles.tabItem} onPress={() => onChange(item.key)}><View style={[mainStyles.tabIcon, active === item.key && mainStyles.tabIconActive]}><Text style={[mainStyles.tabIconText, active === item.key && mainStyles.tabIconTextActive]}>{item.icon}</Text></View><Text style={[mainStyles.tabLabel, active === item.key && mainStyles.tabLabelActive]}>{item.label}</Text></Pressable>)}</View> }

function LegacyOnboardingScreen({ defaultName, completeOnboarding }: { defaultName: string; completeOnboarding: (data: { first_name: string; last_name: string; birth_date: string; gender: 'male' | 'female' | 'other' | 'prefer_not_to_say' }) => Promise<void> }) {
  const [firstName, setFirstName] = useState(defaultName); const [lastName, setLastName] = useState(''); const [birthDate, setBirthDate] = useState<Date | null>(null); const [gender, setGender] = useState<'male' | 'female' | 'other' | 'prefer_not_to_say' | null>(null); const [showDatePicker, setShowDatePicker] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const formatDate = (date: Date) => date.toLocaleDateString('sk-SK', { day: '2-digit', month: '2-digit', year: 'numeric' })
  const isoDate = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
  const submit = async () => { if (!firstName.trim() || !lastName.trim() || !birthDate || !gender) { setError('Vyplň všetky označené údaje.'); return } setBusy(true); setError(''); try { await completeOnboarding({ first_name: firstName, last_name: lastName, birth_date: isoDate(birthDate), gender }) } catch { setError('Údaje sa nepodarilo uložiť. Skús to znova.') } finally { setBusy(false) } }
  return <KeyboardAvoidingView style={styles.flex} behavior={Platform.OS === 'ios' ? 'padding' : undefined}><ScrollView contentContainerStyle={styles.onboardingContainer} keyboardShouldPersistTaps="handled"><Text style={styles.brand}>3×3 <Text style={styles.accent}>SPORT</Text></Text><View style={styles.card}><Text style={styles.eyebrow}>ZÁKLADNÝ PROFIL</Text><Text style={styles.title}>Spoznajme sa.</Text><Text style={styles.subtitle}>Tieto údaje potrebujeme pre tvoj hráčsky profil a správne kategórie.</Text><Field label="Meno"><TextInput value={firstName} onChangeText={setFirstName} placeholder="Napíš svoje meno" placeholderTextColor="#9aa0a8" style={styles.input} autoCapitalize="words" /></Field><Field label="Priezvisko"><TextInput value={lastName} onChangeText={setLastName} placeholder="Napíš svoje priezvisko" placeholderTextColor="#9aa0a8" style={styles.input} autoCapitalize="words" /></Field><Field label="Dátum narodenia"><Pressable style={styles.dateButton} onPress={() => setShowDatePicker(true)}><Text style={birthDate ? styles.dateValue : styles.datePlaceholder}>{birthDate ? formatDate(birthDate) : 'Ťukni a vyber dátum'}</Text><Text style={styles.calendar}>▣</Text></Pressable></Field><Field label="Pohlavie"><View style={styles.genderRow}>{([['male', 'Muž'], ['female', 'Žena'], ['other', 'Iné'], ['prefer_not_to_say', 'Nechcem uviesť']] as const).map(([value, label]) => <Pressable key={value} style={[styles.genderChip, gender === value && styles.genderChipSelected]} onPress={() => setGender(value)}><Text style={[styles.genderText, gender === value && styles.genderTextSelected]}>{gender === value ? '✓ ' : ''}{label}</Text></Pressable>)}</View></Field>{error ? <Text style={styles.error}>{error}</Text> : null}<Pressable style={[styles.continueButton, busy && styles.continueButtonDisabled]} disabled={busy} onPress={() => void submit()}><Text style={styles.continueText}>{busy ? 'Ukladám…' : 'Pokračovať  →'}</Text></Pressable></View></ScrollView><DatePickerModal visible={showDatePicker} initialDate={birthDate} onClose={() => setShowDatePicker(false)} onSelect={date => { setBirthDate(date); setShowDatePicker(false) }} /></KeyboardAvoidingView>
}

function CachedOnboardingScreen({ defaultName, completeOnboarding }: { defaultName: string; completeOnboarding: (data: { nickname: string; first_name: string; last_name: string; birth_date: string; gender: 'male' | 'female' | 'other' | 'prefer_not_to_say'; school_code: string; district_city: string }) => Promise<void> }) {
  const [nickname, setNickname] = useState(''); const [firstName, setFirstName] = useState(defaultName); const [lastName, setLastName] = useState(''); const [birthDate, setBirthDate] = useState<Date | null>(null); const [gender, setGender] = useState<'male' | 'female' | 'other' | 'prefer_not_to_say' | null>(null); const [schools, setSchools] = useState<School[]>([]); const [cities, setCities] = useState<DistrictCity[]>([]); const [schoolQuery, setSchoolQuery] = useState(''); const [cityQuery, setCityQuery] = useState(''); const [school, setSchool] = useState<School | null>(null); const [city, setCity] = useState<DistrictCity | null>(null); const [showDatePicker, setShowDatePicker] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  useEffect(() => { void Promise.all([loadSchools(), loadDistrictCities()]).then(([nextSchools, nextCities]) => { setSchools(nextSchools); setCities(nextCities) }).catch(() => setError('Zoznam škôl sa nepodarilo načítať. Skús to znova.')) }, [])
  const formatDate = (date: Date) => date.toLocaleDateString('sk-SK', { day: '2-digit', month: '2-digit', year: 'numeric' })
  const isoDate = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
  const normalized = (value: string) => value.toLocaleLowerCase('sk-SK')
  const schoolMatches = schoolQuery.trim().length < 2 ? [] : schools.filter(item => normalized(`${item.name} ${item.municipality}`).includes(normalized(schoolQuery))).slice(0, 4)
  const cityMatches = cityQuery.trim().length < 1 ? [] : cities.filter(item => normalized(`${item.name} ${item.district}`).includes(normalized(cityQuery))).slice(0, 4)
  const submit = async () => { if (!nickname.trim() || !firstName.trim() || !lastName.trim() || !birthDate || !gender || !school || !city) { setError('Vyplň všetky označené údaje a vyber školu aj okresné mesto zo zoznamu.'); return } setBusy(true); setError(''); try { await completeOnboarding({ nickname, first_name: firstName, last_name: lastName, birth_date: isoDate(birthDate), gender, school_code: school.code, district_city: city.name }) } catch { setError('Údaje sa nepodarilo uložiť. Skontroluj nick a skús to znova.') } finally { setBusy(false) } }
  return <KeyboardAvoidingView style={styles.flex} behavior={Platform.OS === 'ios' ? 'padding' : undefined}><ScrollView contentContainerStyle={styles.onboardingContainer} keyboardShouldPersistTaps="handled"><Text style={styles.brand}>3×3 <Text style={styles.accent}>SPORT</Text></Text><View style={styles.card}><Text style={styles.eyebrow}>ZÁKLADNÝ PROFIL</Text><Text style={styles.title}>Spoznajme sa.</Text><Text style={styles.subtitle}>Údaje potrebujeme pre tvoj hráčsky profil a správne kategórie.</Text><Field label="Nick"><TextInput value={nickname} onChangeText={setNickname} placeholder="napr. martin_33" placeholderTextColor="#9aa0a8" style={styles.input} autoCapitalize="none" autoCorrect={false} /></Field><Field label="Meno"><TextInput value={firstName} onChangeText={setFirstName} placeholder="Napíš svoje meno" placeholderTextColor="#9aa0a8" style={styles.input} autoCapitalize="words" /></Field><Field label="Priezvisko"><TextInput value={lastName} onChangeText={setLastName} placeholder="Napíš svoje priezvisko" placeholderTextColor="#9aa0a8" style={styles.input} autoCapitalize="words" /></Field><Field label="Škola"><TextInput value={school ? `${school.name} · ${school.municipality}` : schoolQuery} onChangeText={value => { setSchool(null); setSchoolQuery(value) }} placeholder="Začni písať názov alebo mesto" placeholderTextColor="#9aa0a8" style={styles.input} />{schoolMatches.map(item => <Pressable key={item.code} style={styles.catalogOption} onPress={() => { setSchool(item); setSchoolQuery('') }}><Text style={styles.catalogOptionTitle}>{item.name}</Text><Text style={styles.catalogOptionHint}>{item.municipality}</Text></Pressable>)}</Field><Field label="Okresné mesto"><TextInput value={city ? city.name : cityQuery} onChangeText={value => { setCity(null); setCityQuery(value) }} placeholder="Začni písať okresné mesto" placeholderTextColor="#9aa0a8" style={styles.input} />{cityMatches.map(item => <Pressable key={item.id} style={styles.catalogOption} onPress={() => { setCity(item); setCityQuery('') }}><Text style={styles.catalogOptionTitle}>{item.name}</Text><Text style={styles.catalogOptionHint}>Okres {item.district}</Text></Pressable>)}</Field><Field label="Dátum narodenia"><Pressable style={styles.dateButton} onPress={() => setShowDatePicker(true)}><Text style={birthDate ? styles.dateValue : styles.datePlaceholder}>{birthDate ? formatDate(birthDate) : 'Ťukni a vyber dátum'}</Text><Text style={styles.calendar}>▣</Text></Pressable></Field><Field label="Pohlavie"><View style={styles.genderRow}>{([['male', 'Muž'], ['female', 'Žena'], ['other', 'Iné'], ['prefer_not_to_say', 'Nechcem uviesť']] as const).map(([value, label]) => <Pressable key={value} style={[styles.genderChip, gender === value && styles.genderChipSelected]} onPress={() => setGender(value)}><Text style={[styles.genderText, gender === value && styles.genderTextSelected]}>{gender === value ? '✓ ' : ''}{label}</Text></Pressable>)}</View></Field>{error ? <Text style={styles.error}>{error}</Text> : null}<Pressable style={[styles.continueButton, busy && styles.continueButtonDisabled]} disabled={busy} onPress={() => void submit()}><Text style={styles.continueText}>{busy ? 'Ukladám…' : 'Pokračovať  →'}</Text></Pressable></View></ScrollView><DatePickerModal visible={showDatePicker} initialDate={birthDate} onClose={() => setShowDatePicker(false)} onSelect={date => { setBirthDate(date); setShowDatePicker(false) }} /></KeyboardAvoidingView>
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <View style={styles.field}><Text style={styles.label}>{label}</Text>{children}</View> }

function OnboardingScreen({ defaultName, completeOnboarding }: { defaultName: string; completeOnboarding: (data: { nickname: string; first_name: string; last_name: string; birth_date: string; gender: 'male' | 'female' | 'other' | 'prefer_not_to_say'; school_code: string; district_city: string }) => Promise<void> }) {
  const [nickname, setNickname] = useState(''); const [firstName, setFirstName] = useState(defaultName); const [lastName, setLastName] = useState(''); const [birthDate, setBirthDate] = useState<Date | null>(null); const [gender, setGender] = useState<'male' | 'female' | 'other' | 'prefer_not_to_say' | null>(null); const [schoolQuery, setSchoolQuery] = useState(''); const [cityQuery, setCityQuery] = useState(''); const [schools, setSchools] = useState<School[]>([]); const [cities, setCities] = useState<DistrictCity[]>([]); const [school, setSchool] = useState<School | null>(null); const [city, setCity] = useState<DistrictCity | null>(null); const [showDatePicker, setShowDatePicker] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  useEffect(() => { if (school || schoolQuery.trim().length < 2) return setSchools([]); const id = setTimeout(() => { void searchSchools(schoolQuery).then(setSchools).catch(() => setSchools([])) }, 300); return () => clearTimeout(id) }, [schoolQuery, school])
  useEffect(() => { if (city || !cityQuery.trim()) return setCities([]); const id = setTimeout(() => { void searchDistrictCities(cityQuery).then(setCities).catch(() => setCities([])) }, 300); return () => clearTimeout(id) }, [cityQuery, city])
  const submit = async () => { if (!nickname.trim() || !firstName.trim() || !lastName.trim() || !birthDate || !gender || !school || !city) return setError('Vyplň všetky údaje a zvoľ školu a mesto zo zoznamu.'); setBusy(true); setError(''); try { const d = `${birthDate.getFullYear()}-${String(birthDate.getMonth() + 1).padStart(2, '0')}-${String(birthDate.getDate()).padStart(2, '0')}`; await completeOnboarding({ nickname, first_name: firstName, last_name: lastName, birth_date: d, gender, school_code: school.code, district_city: city.name }) } catch { setError('Údaje sa nepodarilo uložiť.') } finally { setBusy(false) } }
  return <KeyboardAvoidingView style={styles.flex} behavior={Platform.OS === 'ios' ? 'padding' : 'height'}><ScrollView contentContainerStyle={styles.onboardingContainer} keyboardShouldPersistTaps="always" keyboardDismissMode="none"><Text style={styles.brand}>3×3 <Text style={styles.accent}>SPORT</Text></Text><View style={styles.card}><Text style={styles.title}>Spoznajme sa.</Text><Field label="Nick"><TextInput style={styles.input} value={nickname} onChangeText={setNickname} autoCapitalize="none" placeholder="napr. martin_33" placeholderTextColor="#9aa0a8" /></Field><Field label="Meno"><TextInput style={styles.input} value={firstName} onChangeText={setFirstName} placeholderTextColor="#9aa0a8" /></Field><Field label="Priezvisko"><TextInput style={styles.input} value={lastName} onChangeText={setLastName} placeholderTextColor="#9aa0a8" /></Field><Field label="Škola"><TextInput style={styles.input} value={school ? `${school.name} · ${school.municipality}` : schoolQuery} onChangeText={v => { setSchool(null); setSchoolQuery(v) }} placeholder="Napíš aspoň 2 znaky" placeholderTextColor="#9aa0a8" />{schools.map(item => <Pressable key={item.code} style={catalogStyles.option} onPress={() => setSchool(item)}><Text style={catalogStyles.optionTitle}>{item.name}</Text><Text style={catalogStyles.optionHint}>{item.municipality}</Text></Pressable>)}</Field><Field label="Okresné mesto"><TextInput style={styles.input} value={city ? city.name : cityQuery} onChangeText={v => { setCity(null); setCityQuery(v) }} placeholder="Napíš mesto" placeholderTextColor="#9aa0a8" />{cities.map(item => <Pressable key={item.id} style={catalogStyles.option} onPress={() => setCity(item)}><Text style={catalogStyles.optionTitle}>{item.name}</Text><Text style={catalogStyles.optionHint}>Okres {item.district}</Text></Pressable>)}</Field><Field label="Dátum narodenia"><Pressable style={styles.dateButton} onPress={() => setShowDatePicker(true)}><Text style={birthDate ? styles.dateValue : styles.datePlaceholder}>{birthDate ? birthDate.toLocaleDateString('sk-SK') : 'Vyber dátum'}</Text></Pressable></Field><Field label="Pohlavie"><View style={styles.genderRow}>{([['male', 'Muž'], ['female', 'Žena'], ['other', 'Iné']] as const).map(([v, label]) => <Pressable key={v} style={[styles.genderChip, gender === v && styles.genderChipSelected]} onPress={() => setGender(v)}><Text style={styles.genderText}>{label}</Text></Pressable>)}</View></Field>{error ? <Text style={styles.error}>{error}</Text> : null}<Pressable style={styles.continueButton} disabled={busy} onPress={() => void submit()}><Text style={styles.continueText}>{busy ? 'Ukladám…' : 'Pokračovať →'}</Text></Pressable></View></ScrollView><DatePickerModal visible={showDatePicker} initialDate={birthDate} onClose={() => setShowDatePicker(false)} onSelect={d => { setBirthDate(d); setShowDatePicker(false) }} /></KeyboardAvoidingView>
}

const catalogStyles = StyleSheet.create({ option: { backgroundColor: '#22252b', borderColor: '#343841', borderWidth: 1, borderRadius: 10, padding: 10, gap: 2 }, optionTitle: { color: '#f3f4f6', fontSize: 13, fontWeight: '700' }, optionHint: { color: '#9aa0a8', fontSize: 12 } })

function DatePickerModal({ visible, initialDate, onClose, onSelect }: { visible: boolean; initialDate: Date | null; onClose: () => void; onSelect: (date: Date) => void }) { const base = initialDate ?? new Date(2000, 0, 1); const [year, setYear] = useState(base.getFullYear()); const [month, setMonth] = useState(base.getMonth()); const [day, setDay] = useState(base.getDate()); const months = ['Jan', 'Feb', 'Mar', 'Apr', 'Máj', 'Jún', 'Júl', 'Aug', 'Sep', 'Okt', 'Nov', 'Dec']; const days = Array.from({ length: new Date(year, month + 1, 0).getDate() }, (_, index) => index + 1); return <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}><View style={styles.modalOverlay}><View style={styles.modalSheet}><Text style={styles.modalTitle}>Vyber dátum narodenia</Text><Text style={styles.modalHint}>Najprv rok, potom mesiac a deň.</Text><Text style={styles.pickerLabel}>Rok</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.optionRow}>{Array.from({ length: 100 }, (_, index) => new Date().getFullYear() - index).map(value => <Pressable key={value} style={[styles.dateOption, year === value && styles.dateOptionSelected]} onPress={() => setYear(value)}><Text style={[styles.dateOptionText, year === value && styles.dateOptionTextSelected]}>{value}</Text></Pressable>)}</ScrollView><Text style={styles.pickerLabel}>Mesiac</Text><View style={styles.monthGrid}>{months.map((name, index) => <Pressable key={name} style={[styles.monthOption, month === index && styles.dateOptionSelected]} onPress={() => setMonth(index)}><Text style={[styles.dateOptionText, month === index && styles.dateOptionTextSelected]}>{name}</Text></Pressable>)}</View><Text style={styles.pickerLabel}>Deň</Text><View style={styles.dayGrid}>{days.map(value => <Pressable key={value} style={[styles.dayOption, day === value && styles.dateOptionSelected]} onPress={() => setDay(value)}><Text style={[styles.dateOptionText, day === value && styles.dateOptionTextSelected]}>{value}</Text></Pressable>)}</View><View style={styles.modalActions}><Pressable onPress={onClose}><Text style={styles.cancelText}>Zrušiť</Text></Pressable><Pressable style={styles.saveDateButton} onPress={() => onSelect(new Date(year, month, Math.min(day, days.length)))}><Text style={styles.saveDateText}>Potvrdiť</Text></Pressable></View></View></View></Modal> }

function LoginScreen({ lang, setLang, t }: { lang: 'sk' | 'en'; setLang: (lang: 'sk' | 'en') => void; t: { subtitle: string; google: string; error: string } }) {
  const { developmentSignIn } = useAuth()
  if (Constants.appOwnership === 'expo') return <View style={loginStyles.screen}><View style={loginStyles.card}><Text style={loginStyles.brand}>3×3 <Text style={loginStyles.accent}>SPORT</Text></Text><Text style={loginStyles.title}>Vitaj v hre.</Text><Text style={loginStyles.subtitle}>Nájdi hráčov, eventy a svoj ranking na jednom mieste.</Text><Text style={loginStyles.note}>Expo Go je určené na rýchle testovanie. Google login funguje v development builde Sport.</Text><Pressable style={loginStyles.button} onPress={() => void developmentSignIn()}><Text style={loginStyles.buttonText}>Pokračovať v testovacom režime  →</Text></Pressable></View></View>
  return <GoogleLogin lang={lang} setLang={setLang} t={t} />
}

function GoogleLogin({ lang, setLang, t }: { lang: 'sk' | 'en'; setLang: (lang: 'sk' | 'en') => void; t: { subtitle: string; google: string; error: string } }) {
  const { signIn } = useAuth(); const androidClientId = process.env.EXPO_PUBLIC_GOOGLE_ANDROID_CLIENT_ID ?? ''
  // Return to the root route so the login component remains mounted to receive
  // the AuthSession result instead of leaving the user on a blank callback page.
  const redirectUri = AuthSession.makeRedirectUri({ native: 'com.nmichel.sport:/' })
  const [request, response, promptAsync] = Google.useIdTokenAuthRequest({ androidClientId, webClientId: process.env.EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID, redirectUri })
  const [error, setError] = useState(false); const handledCredential = useRef<string | null>(null)
  useEffect(() => { const credential = response?.type === 'success' ? response.params.id_token : undefined; if (!credential || handledCredential.current === credential) return; handledCredential.current = credential; void signIn(credential).catch(() => setError(true)) }, [response, signIn])
  return <View style={loginStyles.screen}><View style={loginStyles.card}><Text style={loginStyles.brand}>3×3 <Text style={loginStyles.accent}>SPORT</Text></Text><Text style={loginStyles.title}>Vitaj v hre.</Text><Text style={loginStyles.subtitle}>{t.subtitle}</Text><View style={styles.languages}><Button title="SK" onPress={() => setLang('sk')} /><Button title="EN" onPress={() => setLang('en')} /></View><Pressable style={loginStyles.button} disabled={!request || !androidClientId} onPress={() => { setError(false); void promptAsync() }}><Text style={loginStyles.buttonText}>{t.google}</Text></Pressable>{error && <Text style={styles.error}>{t.error}</Text>}</View></View>
}
